import type { Env, Tenant } from './types';
import { PLANS, effectivePlan, reservePlanUsage, finishPlanUsage, planUsage } from './plans';
import { audioSeconds } from './audio-duration';

export async function prepareVoice(env:Env,tenant:Tenant,requestId:string,text:string) {
  if (!env.AI || !env.MEDIA_BUCKET || PLANS[effectivePlan(tenant)].voice===0) return null;
  const usage=await planUsage(env,tenant);
  if((usage.used.voice || 0)>=usage.limits.voice)return null;
  // Portuguese supported by the unified Workers AI model API. The result is a
  // presigned URL; the generated bytes are validated before quota reservation.
  const output=await env.AI.run('xai/grok-tts',{text:text.replace(/[*_~`]/g,''),language:'pt-BR',voice_id:'ara',output_format:{codec:'mp3',sample_rate:24000,bit_rate:128000}});
  const result=output.result as Record<string,unknown>|undefined;
  const url=typeof output.audio==='string'?output.audio:typeof result?.audio==='string'?result.audio:null;
  if(!url || !url.startsWith('https://'))return null;
  const response=await fetch(url,{signal:AbortSignal.timeout(15000)});
  if(!response.ok || !response.body)return null;
  const reader=response.body.getReader(),chunks:Uint8Array[]=[];let length=0;
  while(true){const chunk=await reader.read();if(chunk.done)break;length+=chunk.value.length;
    if(length>10*1024*1024){await reader.cancel();return null;}chunks.push(chunk.value);}
  const bytes=new Uint8Array(length);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}
  const seconds=audioSeconds(bytes.buffer,'audio/mpeg');
  if(seconds===null)return null;
  const quota=await reservePlanUsage(env,tenant,'voice',requestId,seconds);
  if(quota!=='reserved')return null;
  try {
    const key=`tenants/${tenant.id}/${new Date().toISOString().slice(0,7)}/${crypto.randomUUID()}.mp3`;
    await env.MEDIA_BUCKET.put(key,bytes,{httpMetadata:{contentType:'audio/mpeg'}});
    return {bytes,key,mime:'audio/mpeg'};
  } catch(error) {await finishPlanUsage(env,tenant.id,'voice',requestId,true);throw error;}
}
